package weeklyassignments;

public class Program_ForLoop_Reverse {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		for(int i=5;i>=1;)   // this for loop is started from 5 and check condition that
			                    //i>=1 if its true it will print value of i and then it will reduce the value of i by 1 
		{
			System.out.print(i);
			i--;
		}

	}

}
